algorithms.pseudocode:
COMPRESS(i, j, F):
  result = {}
  for α in F:
    s = shift(i, j, α)
    if s ∈ F: result.add(α)
    else: result.add(s)
  return result

FULL_COMPRESS(F, n):
  repeat:
    changed = false
    for i = 0 to n-2:
      for j = i+1 to n-1:
        G = COMPRESS(i, j, F)
        if G ≠ F: F = G; changed = true
  until not changed
  return F
